export function renderInsulationReferenceIllustration(arrangement) {
  const artwork = {
    "service-zone": SERVICE_ZONE,
    "insulation-cover": INSULATION_COVER,
  };
  if (!Object.hasOwn(artwork, arrangement)) throw new TypeError("Unknown insulation arrangement");
  return `<image data-insulation-arrangement="${arrangement}" x="7" y="0" width="44" height="44" href="data:image/jpeg;base64,${artwork[arrangement]}"/>`;
}
